    if not h or any(len(row) != len(grid[0]) for row in grid):
        raise ValueError("grid must be non-empty and rectangular")
    w = len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = {v for row in grid for v in row if v != bg}
    out = [[bg] * w for _ in range(h)]

    for color in colors:
        available = [[grid[r][c] == color for c in range(w)] for r in range(h)]
        while True:
            # Integral image for quick rectangle counts.
            pref = [[0] * (w + 1) for _ in range(h + 1)]
            for r in range(h):
                run = 0
                for c in range(w):
                    run += available[r][c]
                    pref[r + 1][c + 1] = pref[r][c + 1] + run

            best = None
            best_score = 0.0
            for r0 in range(h):
                for r1 in range(r0 + 1, h + 1):
                    rh = r1 - r0
                    for c0 in range(w):
                        for c1 in range(c0 + 1, w + 1):
                            area = rh * (c1 - c0)
                            if area < 4:
                                continue
                            count = (pref[r1][c1] - pref[r0][c1]
                                     - pref[r1][c0] + pref[r0][c0])
                            density = count / area
                            if density < 0.70:
                                continue
                            score = area * density * density
                            if score > best_score:
                                best_score = score
                                best = (r0, r1, c0, c1)
            if best is None:
                break
            r0, r1, c0, c1 = best
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = color
                    available[r][c] = False
    return out


if __name__ == '__main__':
    print('transform module ready')
